-- Star farm master data from VegPro Greenhouse Bay Mapping Star.xlsx + Pest and Disease List.xlsx

values (
  'beee0001-0001-4001-8001-000000000001',
  'Star',
  'Star farm — protected roses',
  'Greenhouse'
)
on conflict (id) do update set
  name = excluded.name,
  location = excluded.location;

values ('ccccccc3-3333-3333-3333-333333333333', 'Cut Rose')
on conflict (id) do update set name = excluded.name;

select 'ccccccc3-3333-3333-3333-333333333333', v from unnest(array[
  'Athena', 'Confidential', 'Escape', 'Fuschiana', 'Inka', 'Madam Red', 'Million Reason', 'Moonwalk', 'Natures White', 'Orange Candy', 'Pink Arrow', 'Red Calypso', 'Revolution', 'Simply Orange', 'Simply Pink'
]::text[]) as v
on conflict (category_id, name) do nothing;

update public.scouting_parameters
set name = 'Other Caterpillars'
where param_key = 'sp-caterpillers';

values ('sd-back-spot', 'disease', 'Back Spot', 16)
on conflict (param_key) do update set name = excluded.name;

-- Replace previous Bemack houses on this farm
delete from public.qr_codes where farm_id = 'beee0001-0001-4001-8001-000000000001';
delete from public.scouting_observations where record_id in (
  select id from public.scouting_records where farm_id = 'beee0001-0001-4001-8001-000000000001'
);
delete from public.scouting_records where farm_id = 'beee0001-0001-4001-8001-000000000001';
delete from public.scouting_rounds where farm_id = 'beee0001-0001-4001-8001-000000000001';
delete from public.spray_treatments where farm_id = 'beee0001-0001-4001-8001-000000000001';
delete from public.infestation_hotspots where farm_id = 'beee0001-0001-4001-8001-000000000001';
update public.activities set greenhouse_id = null
where farm_id = 'beee0001-0001-4001-8001-000000000001';
delete from public.greenhouses where farm_id = 'beee0001-0001-4001-8001-000000000001';


select farm_id, id, 'VEGPRO|STAR|' || name
from public.greenhouses
where farm_id = 'beee0001-0001-4001-8001-000000000001'
on conflict (qr_value) do nothing;

